<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\PublicMfa;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepName;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

/**
 * Login step form for enrolling a new TOTP-based multi-factor authentication device.
 *
 * This form is shown when the authentication pipeline determines that the user must set up
 * MFA for the first time (ERR_NEW_MFA_REQUIRED). It retrieves a fresh TOTP seed from
 * PublicMfa, optionally presenting a QR-code image and a textual seed to the user for
 * import into an authenticator app. The seed is encrypted and round-tripped through the
 * form so the server can verify the first OTP code without persisting the seed prematurely.
 *
 * Only after the user submits a valid OTP code that matches the seed is the seed persisted
 * and the MFA challenge marked as satisfied. A reset button on the form allows generating a
 * new seed if the user needs to restart enrollment.
 *
 * Relationships: uses PublicMfa to generate and verify TOTP data, AuthenticateUser for
 * post-enrolment pre-authentication, HtmlSecurer for encryption and CSRF injection, and
 * DecorateHtml for themed page output.
 */
class NewMfaForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly AuthenticateUser $authenticator,
        private readonly PublicMfa $publicMfa,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer
    ) {
    }

    /**
     * Renders the MFA enrollment page with a QR code or seed text and the OTP input field.
     *
     * Fetches a new TOTP seed from PublicMfa, encrypts it for safe round-tripping in the
     * hidden form field, and emits the QR/message if provided, together with an input for
     * the verification code and a back link.
     */
    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $locale = '';
        $tenant = $input->context->tenant;
        $challenges = $input->challenges;

        $token = $this->publicMfa->configurationForNewMfa($tenant, $challenges->username ?? '');

        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->addSign("bsign"),
            $this->securer->focusOn("mfa_code"),
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get("newmfa.title");
        $errorMessage = $error?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("newmfa.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';
        $help = $translator->get("newmfa.help");
        $code = $translator->get("newmfa.code");
        $send = $translator->get("newmfa.send");

        $backText = $translator->get(
            "newmfa.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $translator->get("newmfa.back-label") . "\" />"]
        );

        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $seed = $this->securer->encrypt($token->seed);
        $message = $token->message !== null && $token->message !== '' ? "<h2>" . $token->message . "</h2>" : "";
        $image = $token->image !== null && $token->image !== '' ? "<img src=\"" . $token->image . "\" />" : "";

        $step = StepName::NEW_MFA->value;
        $backStep = StepName::LOGIN->value;
        $response->getBody()->write($this->decorator->getFullPage(
            $input->request,
            'New mfa',
            $js . <<<HTML
                    <h1>{$title}</h1>
                    <p>{$help}</p>
                    {$error}
                    {$image}
                    {$message}
                    <form method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="seed" value="{$seed}" />
                        <input type="hidden" name="step" value="{$step}" />
                        <label>{$code}
                            <input type="text" name="mfa_code" id="mfa_code" value="" />
                        </label>
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="csid" id="bsign" />
                        <input type="hidden" name="step" value="{$step}" />
                        <input class="inline" type="submit" value="RESET" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="{$backStep}" />
                        {$backText}
                    </form>
                HTML,
            $locale,
            'index',
            $tenant
        ));
        return StepResult::render($response, $input->challenges);
    }

    /**
     * Verifies the submitted OTP code against the round-tripped seed and finalises MFA enrolment.
     *
     * Decrypts the hidden seed field, validates the OTP via PublicMfa, and if successful
     * persists the seed and marks the MFA challenge as satisfied before calling preAuthenticate.
     * Throws LoginException with a wrong-code result when validation fails.
     */
    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $csid = (string) ($input->body['csid'] ?? '');
        $seed = isset($input->body['seed']) ? $this->securer->decrypt((string) $input->body['seed']) : '';
        $code = $input->body['mfa_code'] ?? '';

        if ($seed !== null && $seed !== '' && $this->publicMfa->verifyNewOpt($input->context->tenant, $input->challenges->username ?? '', $seed, $code)) {
            $updated = $input->challenges->withMfa(true);
            $auth = $this->authenticator->preAuthenticate(
                $input->authRequest,
                $updated,
                $input->context->tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce
            );
            return StepResult::proceed($auth, $updated);
        }

        throw new LoginException(auth: AuthenticationResult::newMfaRequired('wrong_auth_code'));
    }
}
